js:
var btn = root.querySelector(".cxb5-wallet-balance__copy");
var num = root.querySelector(".cxb5-wallet-balance__num");
var sr = root.querySelector(".cxb5-wallet-balance__sr");
var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
var target = parseFloat(num.getAttribute("data-value"));

if (reduce) {
  num.textContent = target.toFixed(4);
} else {
  var t0 = null, dur = 900;
  var step = function (ts) {
    if (t0 === null) t0 = ts;
    var p = Math.min(1, (ts - t0) / dur);
    var e = 1 - Math.pow(1 - p, 3);
    num.textContent = (target * e).toFixed(4);
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

var timer = null;
var legacyCopy = function (text) {
  var ta = document.createElement("textarea");
  ta.value = text;
  ta.setAttribute("readonly", "readonly");
  ta.style.position = "fixed";
  ta.style.top = "-1000px";
  ta.style.opacity = "0";
  document.body.appendChild(ta);
  ta.select();
  var ok = false;
  try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
  document.body.removeChild(ta);
  return ok;
};

var flash = function (ok) {
  btn.setAttribute("data-copied", "1");
  sr.textContent = ok ? "Wallet address copied to clipboard" : "Copy failed, select the address manually";
  if (timer) clearTimeout(timer);
  timer = setTimeout(function () {
    btn.removeAttribute("data-copied");
    sr.textContent = "";
  }, 1600);
};

btn.addEventListener("click", function () {
  var text = btn.getAttribute("data-address");
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(function () { flash(true); }, function () { flash(legacyCopy(text)); });
  } else {
    flash(legacyCopy(text));
  }
});

