js:
var input = root.querySelector(".cxb5-token-swap__in");
var out = root.querySelector(".cxb5-token-swap__out");
var flip = root.querySelector(".cxb5-token-swap__flip");
var rateEl = root.querySelector(".cxb5-token-swap__rate");
var minEl = root.querySelector(".cxb5-token-swap__minv");
var symA = root.querySelector(".cxb5-token-swap__symA");
var symB = root.querySelector(".cxb5-token-swap__symB");
var coinA = root.querySelector(".cxb5-token-swap__coin--a");
var coinB = root.querySelector(".cxb5-token-swap__coin--b");
var chips = root.querySelectorAll(".cxb5-token-swap__chip");

var RATE = 3466.2;
var reversed = false;
var slip = 0.5;

var fmt = function (n, d) {
  return n.toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
};

var render = function () {
  var amt = parseFloat(String(input.value).replace(/,/g, ""));
  if (!isFinite(amt) || amt < 0) amt = 0;
  var rate = reversed ? 1 / RATE : RATE;
  var a = reversed ? "USDC" : "ETH";
  var b = reversed ? "ETH" : "USDC";
  var dec = reversed ? 6 : 2;
  var got = amt * rate * 0.9995;
  out.textContent = fmt(got, dec);
  minEl.textContent = fmt(got * (1 - slip / 100), dec) + " " + b;
  rateEl.textContent = "1 " + a + " = " + fmt(rate, reversed ? 6 : 2) + " " + b;
  symA.textContent = a;
  symB.textContent = b;
  coinA.textContent = reversed ? "$" : "Ξ";
  coinB.textContent = reversed ? "Ξ" : "$";
};

input.addEventListener("input", function () {
  var clean = input.value.replace(/[^0-9.]/g, "").replace(/(\..*)\./g, "$1");
  if (clean !== input.value) input.value = clean;
  render();
});

input.addEventListener("blur", function () {
  var amt = parseFloat(input.value);
  input.value = isFinite(amt) && amt > 0 ? String(amt) : "0";
  render();
});

flip.addEventListener("click", function () {
  reversed = !reversed;
  flip.setAttribute("data-rev", reversed ? "1" : "0");
  input.value = reversed ? "5000" : "1.50";
  input.setAttribute("aria-label", "Amount you pay in " + (reversed ? "USDC" : "ETH"));
  render();
});

Array.prototype.forEach.call(chips, function (chip) {
  chip.addEventListener("click", function () {
    Array.prototype.forEach.call(chips, function (c) { c.setAttribute("aria-pressed", "false"); });
    chip.setAttribute("aria-pressed", "true");
    slip = parseFloat(chip.getAttribute("data-slip"));
    render();
  });
});

render();

