@media (prefers-reduced-motion:reduce){.cxb5-gas-fee__ind,.cxb5-gas-fee__lab,.cxb5-gas-fee__name,.cxb5-gas-fee__gwei,.cxb5-gas-fee__eta{transition:none}}

js:
var radios = root.querySelectorAll(".cxb5-gas-fee__radio");
var cost = root.querySelector(".cxb5-gas-fee__cost");
var usd = root.querySelector(".cxb5-gas-fee__usd");
var basev = root.querySelector(".cxb5-gas-fee__basev");
var gname = "cxb5-gas-fee-" + Math.random().toString(36).slice(2, 9);

var apply = function (r) {
  root.style.setProperty("--cxb5-gas-fee-i", r.getAttribute("data-i"));
  cost.textContent = r.getAttribute("data-eth") + " ETH";
  usd.textContent = "$" + r.getAttribute("data-usd");
};

Array.prototype.forEach.call(radios, function (r) {
  r.name = gname;
  r.addEventListener("change", function () { if (r.checked) apply(r); });
  if (r.checked) apply(r);
});

var base = 18.4;
var drift = setInterval(function () {
  base = Math.max(9, Math.min(46, base + (Math.random() - 0.48) * 1.6));
  basev.textContent = base.toFixed(1);
}, 2600);

root.addEventListener("cxb5-gas-fee:destroy", function () { clearInterval(drift); });

