var glare = root.querySelector(".cxb5-nft-card__glare");
var mq = window.matchMedia ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
var reduce = mq ? mq.matches : false;
var raf = 0;

var reset = function () {
  root.style.setProperty("--cxb5-nft-card-rx", "0");
  root.style.setProperty("--cxb5-nft-card-ry", "0");
  root.style.setProperty("--cxb5-nft-card-gx", "50%");
  root.style.setProperty("--cxb5-nft-card-gy", "50%");
};

var move = function (ev) {
  if (reduce) return;
  if (raf) return;
  raf = requestAnimationFrame(function () {
    raf = 0;
    var r = tilt.getBoundingClientRect();
    var px = (ev.clientX - r.left) / r.width;
    var py = (ev.clientY - r.top) / r.height;
    root.style.setProperty("--cxb5-nft-card-ry", ((px - 0.5) * 13).toFixed(2));
    root.style.setProperty("--cxb5-nft-card-rx", ((0.5 - py) * 10).toFixed(2));
    root.style.setProperty("--cxb5-nft-card-gx", (px * 100).toFixed(1) + "%");
    root.style.setProperty("--cxb5-nft-card-gy", (py * 100).toFixed(1) + "%");
  });
};

root.addEventListener("pointermove", move);
root.addEventListener("pointerleave", reset);
root.addEventListener("blur", reset);
root.addEventListener("focus", function () {
  if (reduce) return;
  root.style.setProperty("--cxb5-nft-card-gx", "32%");
