js:
var val = root.querySelector(".cxb5-stake-panel__val");
var ring = root.querySelector(".cxb5-stake-panel__ring");
var eta = root.querySelector(".cxb5-stake-panel__eta");
var claim = root.querySelector(".cxb5-stake-panel__claim");
var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

var STAKE = 12.5;
var APY = 0.0384;
var PER_SEC = STAKE * APY / 31556952;
var accrued = 0.04217402;
var secsLeft = 4 * 3600 + 12 * 60;
var EPOCH = 6 * 3600;
var last = Date.now();
var tickTimer = null;

var paint = function () {
  var now = Date.now();
  var dt = (now - last) / 1000;
  last = now;
  accrued += PER_SEC * dt;
  secsLeft -= dt;
  if (secsLeft <= 0) secsLeft += EPOCH;
  val.textContent = accrued.toFixed(8);
  val.setAttribute("data-tick", "1");
  if (tickTimer) clearTimeout(tickTimer);
  tickTimer = setTimeout(function () { val.removeAttribute("data-tick"); }, 90);
  var h = Math.floor(secsLeft / 3600);
  var m = Math.floor((secsLeft % 3600) / 60);
  eta.textContent = h + "h " + (m < 10 ? "0" : "") + m + "m";
  ring.style.setProperty("--cxb5-stake-panel-p", (100 * (1 - secsLeft / EPOCH)).toFixed(2));
};

paint();
var loop = setInterval(paint, reduce ? 1000 : 120);

claim.addEventListener("click", function () {
  claim.setAttribute("data-done", "1");
  claim.textContent = "Restaked " + accrued.toFixed(6) + " ETH";
  setTimeout(function () {
    claim.removeAttribute("data-done");
    claim.textContent = "Claim & restake";
  }, 2200);
  accrued = 0;
});

root.addEventListener("cxb5-stake-panel:destroy", function () { clearInterval(loop); });

