js:
var C = 119.38;
var prog = root.querySelector(".cxb5-tx-confirm__prog");
var count = root.querySelector(".cxb5-tx-confirm__count");
var nEl = root.querySelector(".cxb5-tx-confirm__n");
var status = root.querySelector(".cxb5-tx-confirm__status");
var block = root.querySelector(".cxb5-tx-confirm__block");
var hashBtn = root.querySelector(".cxb5-tx-confirm__hash");
var sr = root.querySelector(".cxb5-tx-confirm__sr");

var TOTAL = 12;
var START_BLOCK = 21904318;
var n = 0;
var timer = null;

var paint = function () {
  prog.style.strokeDashoffset = String(C * (1 - n / TOTAL));
  count.textContent = String(n);
  nEl.textContent = String(n);
  block.textContent = "Block " + (START_BLOCK + n).toLocaleString("en-US");
  if (n >= TOTAL) {
    root.setAttribute("data-state", "done");
    status.textContent = "Confirmed";
  } else {
    root.setAttribute("data-state", "pending");
    status.textContent = n === 0 ? "Pending" : "Confirming";
  }
};

var step = function () {
  if (n >= TOTAL) {
    n = 0;
    paint();
    timer = setTimeout(step, 1400);
    return;
  }
  n += 1;
  paint();
  timer = setTimeout(step, n >= TOTAL ? 3200 : 1150);
};

paint();
timer = setTimeout(step, 900);

var copyFlash = null;
hashBtn.addEventListener("click", function () {
  var text = hashBtn.getAttribute("data-hash");
  var done = function () {
    hashBtn.setAttribute("data-copied", "1");
    sr.textContent = "Transaction hash copied";
    if (copyFlash) clearTimeout(copyFlash);
    copyFlash = setTimeout(function () {
      hashBtn.removeAttribute("data-copied");
      sr.textContent = "";
    }, 1500);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done, done);
  } else {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.top = "-1000px";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (e) {}
    document.body.removeChild(ta);
    done();
  }
});

root.addEventListener("cxb5-tx-confirm:destroy", function () { if (timer) clearTimeout(timer); });

