var cur = root.querySelector(".cxb5-network-select__cur");
var curGlyph = trigger.querySelector(".cxb5-network-select__glyph");
var ms = root.querySelector(".cxb5-network-select__ms");
var gas = root.querySelector(".cxb5-network-select__gas");
var blk = root.querySelector(".cxb5-network-select__blk");
var bars = Array.prototype.slice.call(root.querySelectorAll(".cxb5-network-select__bar"));
var pingv = root.querySelector(".cxb5-network-select__pingv");

var drawBars = function (baseMs) {
  var sum = 0;
  bars.forEach(function (b, i) {
    var jitter = 0.72 + 0.56 * Math.abs(Math.sin(baseMs * 0.37 + i * 1.9));
    var v = baseMs * jitter;
    sum += v;
    b.style.setProperty("--cxb5-network-select-h", Math.max(14, Math.min(100, v * 1.55)).toFixed(0));
  });
  pingv.textContent = "avg " + Math.round(sum / bars.length) + " ms";
};

var open = function (focusIndex) {
  panel.hidden = false;
  trigger.setAttribute("aria-expanded", "true");
  var i = typeof focusIndex === "number" ? focusIndex : Math.max(0, opts.findIndex(function (o) { return o.getAttribute("aria-selected") === "true"; }));
  opts[i].focus();
};

var close = function (refocus) {
  panel.hidden = true;
  trigger.setAttribute("aria-expanded", "false");
  if (refocus) trigger.focus();
};

var select = function (opt) {
  opts.forEach(function (o) { o.setAttribute("aria-selected", o === opt ? "true" : "false"); });
  cur.textContent = opt.getAttribute("data-name");
  curGlyph.setAttribute("data-net", opt.getAttribute("data-net"));
  ms.textContent = opt.getAttribute("data-ms") + " ms";
  gas.textContent = "Gas " + opt.getAttribute("data-gas");
  blk.textContent = "Block " + opt.getAttribute("data-blk");
  drawBars(parseInt(opt.getAttribute("data-ms"), 10));
};

drawBars(42);

trigger.addEventListener("click", function () {
  if (panel.hidden) open(); else close(true);
});

trigger.addEventListener("keydown", function (e) {
  if (e.key === "ArrowDown" || e.key === "Down") { e.preventDefault(); open(); }
  else if (e.key === "ArrowUp" || e.key === "Up") { e.preventDefault(); open(opts.length - 1); }
});

panel.addEventListener("keydown", function (e) {
  var i = opts.indexOf(document.activeElement);
  if (e.key === "Escape" || e.key === "Esc") { e.preventDefault(); close(true); }
  else if (e.key === "ArrowDown" || e.key === "Down") { e.preventDefault(); opts[(i + 1) % opts.length].focus(); }
  else if (e.key === "ArrowUp" || e.key === "Up") { e.preventDefault(); opts[(i - 1 + opts.length) % opts.length].focus(); }
  else if (e.key === "Home") { e.preventDefault(); opts[0].focus(); }
  else if (e.key === "End") { e.preventDefault(); opts[opts.length - 1].focus(); }
  else if (e.key === "Tab") { close(false); }
});

opts.forEach(function (opt) {
  opt.addEventListener("click", function () { select(opt); close(true); });
});

var onDocDown = function (e) {
  if (!panel.hidden && !root.contains(e.target)) close(false);
};
document.addEventListener("pointerdown", onDocDown);
root.addEventListener("cxb5-network-select:destroy", function () { document.removeEventListener("pointerdown", onDocDown); });

