var range = root.querySelector(".cxb5-price-alert__range");
var thr = root.querySelector(".cxb5-price-alert__thr");
var target = root.querySelector(".cxb5-price-alert__target");
var away = root.querySelector(".cxb5-price-alert__away");
var dirBtns = Array.prototype.slice.call(root.querySelectorAll(".cxb5-price-alert__dirbtn"));

var SPOT = 96412;
var dir = "above";

var yFor = function (price) { return 49 - (price - 90000) * 0.0032143; };

var render = function () {
  var v = parseInt(range.value, 10);
  var y = yFor(v).toFixed(2);
  thr.setAttribute("y1", y);
  thr.setAttribute("y2", y);
  root.style.setProperty("--cxb5-price-alert-mark", dir === "above" ? "var(--cxb5-price-alert-up)" : "var(--cxb5-price-alert-dn)");
  target.textContent = dir + " $" + v.toLocaleString("en-US");
  var pct = (v - SPOT) / SPOT * 100;
  var arrow = pct >= 0 ? "▲" : "▼";
  away.textContent = arrow + " " + Math.abs(pct).toFixed(2) + "% away";
  away.style.color = pct >= 0 ? "var(--cxb5-price-alert-up)" : "var(--cxb5-price-alert-dn)";
};

range.addEventListener("input", render);

dirBtns.forEach(function (b) {
  b.addEventListener("click", function () {
    dir = b.getAttribute("data-dir");
    dirBtns.forEach(function (o) { o.setAttribute("aria-pressed", o === b ? "true" : "false"); });
    render();
  });
});

render();

