var btn = root.querySelector('.cx5-wallet-balance-copy');
var tag = root.querySelector('.cx5-wallet-balance-tag');
var full = '0x7A3f4B92cCd18eA5f1B7a0D2e63F4A8b71dE9C21';
var timer = null;
btn.title = full;
btn.setAttribute('aria-label', 'Copy wallet address ' + full);
function done(ok){
  if (timer) clearTimeout(timer);
  tag.textContent = ok ? 'Copied' : 'Press Cmd C';
  if (ok) btn.classList.add('cx5-wallet-balance-ok');
  timer = setTimeout(function(){
    tag.textContent = 'Copy';
    btn.classList.remove('cx5-wallet-balance-ok');
  }, 1500);
}
function legacy(){
  var ta = document.createElement('textarea');
  ta.value = full;
  ta.setAttribute('readonly', 'readonly');
  ta.style.position = 'fixed';
  ta.style.top = '-1000px';
  ta.style.opacity = '0';
  root.appendChild(ta);
  var ok = false;
  try { ta.select(); ok = document.execCommand('copy'); } catch (e) { ok = false; }
  root.removeChild(ta);
  done(ok);
}
btn.addEventListener('click', function(){
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(full).then(function(){ done(true); }, legacy);
  } else { legacy(); }
});

