js:
var input = root.querySelector('.cx5-token-swap-in');
var out = root.querySelector('.cx5-token-swap-out');
var flip = root.querySelector('.cx5-token-swap-flip');
var pxEl = root.querySelector('.cx5-token-swap-px');
var baseEl = root.querySelector('.cx5-token-swap-base');
var quoteEl = root.querySelector('.cx5-token-swap-quote');
var minEl = root.querySelector('.cx5-token-swap-minv');
var minSym = root.querySelector('.cx5-token-swap-minsym');
var symA = root.querySelector('.cx5-token-swap-sym-a');
var symB = root.querySelector('.cx5-token-swap-sym-b');
var markA = root.querySelector('.cx5-token-swap-mark-a');
var markB = root.querySelector('.cx5-token-swap-mark-b');
var chips = root.querySelectorAll('.cx5-token-swap-chip');
var RATE = 3281.40, inverted = false, slip = 0.5, spun = false;

function fmt(n, d){
  return n.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
}
function render(flash){
  var rate = inverted ? 1 / RATE : RATE;
  var amt = parseFloat(input.value.replace(/,/g, ''));
  if (!isFinite(amt) || amt < 0) amt = 0;
  var gross = amt * rate * 0.997;
  var dp = inverted ? 5 : 2;
  out.textContent = fmt(gross, dp);
  minEl.textContent = fmt(gross * (1 - slip / 100), dp);
  pxEl.textContent = fmt(rate, inverted ? 6 : 2);
  baseEl.textContent = inverted ? 'USDC' : 'ETH';
  quoteEl.textContent = inverted ? 'ETH' : 'USDC';
  minSym.textContent = inverted ? 'ETH' : 'USDC';
  if (flash) {
    out.classList.add('cx5-token-swap-flash');
    setTimeout(function(){ out.classList.remove('cx5-token-swap-flash'); }, 260);
  }
}
input.addEventListener('input', function(){
  var clean = input.value.replace(/[^0-9.]/g, '').replace(/(\..*)\./g, '$1');
  if (clean !== input.value) input.value = clean;
  render(false);
});
flip.addEventListener('click', function(){
  inverted = !inverted;
  spun = !spun;
  flip.classList.toggle('cx5-token-swap-spin', spun);
  var a = symA.textContent, b = symB.textContent;
  symA.textContent = b; symB.textContent = a;
  markA.textContent = inverted ? '$' : 'Ξ';
  markB.textContent = inverted ? 'Ξ' : '$';
  input.value = inverted ? '5000' : '1.50';
  render(true);
});
for (var i = 0; i < chips.length; i++) {
  chips[i].addEventListener('click', function(e){
    var btn = e.currentTarget;
    for (var j = 0; j < chips.length; j++) {
      chips[j].classList.remove('cx5-token-swap-chip-on');
      chips[j].setAttribute('aria-pressed', 'false');
    }
    btn.classList.add('cx5-token-swap-chip-on');
    btn.setAttribute('aria-pressed', 'true');
    slip = parseFloat(btn.getAttribute('data-slip'));
    render(true);
  });
}
