var seg = root.querySelector('.cx5-gas-speed-seg');
var thumb = root.querySelector('.cx5-gas-speed-thumb');
var radios = root.querySelectorAll('.cx5-gas-speed-radio');
var etaEl = root.querySelector('.cx5-gas-speed-etav');
var usdEl = root.querySelector('.cx5-gas-speed-usd');
var baseEl = root.querySelector('.cx5-gas-speed-basev');
var trend = root.querySelector('.cx5-gas-speed-trend');
var group = 'cx5gas' + Math.random().toString(36).slice(2, 9);
var base = 18.4;

function sync(){
  for (var i = 0; i < radios.length; i++) {
    radios[i].name = group;
    if (radios[i].checked) {
      thumb.style.transform = 'translateX(calc(' + i + ' * (100% + 2px)))';
      etaEl.textContent = radios[i].getAttribute('data-eta');
      usdEl.textContent = radios[i].getAttribute('data-usd');
    }
  }
}
seg.addEventListener('change', sync);
sync();

var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  var step = (Math.random() - 0.45) * 1.6;
  var next = Math.min(46, Math.max(9, base + step));
  var up = next >= base;
  base = next;
  baseEl.textContent = base.toFixed(1);
  trend.textContent = up ? '▲' : '▼';
  trend.classList.toggle('cx5-gas-speed-down', !up);
}, 2600);

