js:
var rval = root.querySelector('.cx5-stake-apy-rval');
var claim = root.querySelector('.cx5-stake-apy-claim');
var arc = root.querySelector('.cx5-stake-apy-arc');
var pct = root.querySelector('.cx5-stake-apy-pct');
var epoch = 68, rewards = 3.847213, staked = 1250, apy = 0.0734;
var perMs = (staked * apy) / 31536000000;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var last = Date.now(), raf = 0, slow = 0;

rval.setAttribute('aria-label', 'Rewards accruing, in SOL');
claim.setAttribute('aria-label', 'Claim staking rewards');

function paint(){
  rval.textContent = rewards.toFixed(6);
}
function step(){
  var now = Date.now();
  rewards += (now - last) * perMs;
  last = now;
  paint();
  if (root.isConnected) raf = requestAnimationFrame(step);
}
if (reduce) {
  slow = setInterval(function(){
    if (!root.isConnected) { clearInterval(slow); return; }
    var now = Date.now();
    rewards += (now - last) * perMs;
    last = now;
    paint();
  }, 1000);
} else {
  raf = requestAnimationFrame(step);
}
var ep = setInterval(function(){
  if (!root.isConnected) { clearInterval(ep); return; }
  epoch = epoch >= 100 ? 1 : epoch + 1;
  pct.textContent = String(epoch);
  arc.style.strokeDashoffset = String((113.1 * (1 - epoch / 100)).toFixed(1));
}, 2200);
claim.addEventListener('click', function(){
  if (rewards <= 0) return;
  staked += rewards;
  rewards = 0;
  perMs = (staked * apy) / 31536000000;
  paint();
  root.querySelector('.cx5-stake-apy-amt').textContent = staked.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  root.querySelector('.cx5-stake-apy-amt').classList.add('cx5-stake-apy-flash');
  claim.textContent = 'Claimed';
  claim.disabled = true;
  setTimeout(function(){
    claim.textContent = 'Claim';
    claim.disabled = false;
    root.querySelector('.cx5-stake-apy-amt').classList.remove('cx5-stake-apy-flash');
  }, 1600);
});

