js:
var ladder = root.querySelector('.cx5-tx-confirm-ladder');
var nEl = root.querySelector('.cx5-tx-confirm-n');
var stateEl = root.querySelector('.cx5-tx-confirm-state');
var bnEl = root.querySelector('.cx5-tx-confirm-bn');
var TOTAL = 12, n = 3, block = 21483902, segs = [];

for (var i = 0; i < TOTAL; i++) {
  var s = document.createElement('span');
  s.className = 'cx5-tx-confirm-seg';
  ladder.appendChild(s);
  segs.push(s);
}
function paint(){
  for (var i = 0; i < TOTAL; i++) {
    segs[i].classList.toggle('cx5-tx-confirm-fill', i < n);
    segs[i].classList.toggle('cx5-tx-confirm-live', i === n - 1 && n < TOTAL);
  }
  nEl.textContent = String(n);
  ladder.setAttribute('aria-label', n + ' of ' + TOTAL + ' confirmations');
  bnEl.textContent = block.toLocaleString('en-US');
  if (n >= TOTAL) {
    root.classList.add('cx5-tx-confirm-done');
    stateEl.textContent = 'Finalized';
  }
}
paint();
var timer = 0;
function tick(){
  if (!root.isConnected) return;
  if (n < TOTAL) {
    n += 1; block += 1;
    paint();
    timer = setTimeout(tick, 1000);
  } else {
    timer = setTimeout(function(){
      if (!root.isConnected) return;
      n = 1; block += 1;
      root.classList.remove('cx5-tx-confirm-done');
      stateEl.textContent = 'Confirming';
      paint();
      timer = setTimeout(tick, 1000);
    }, 3400);
  }
}
timer = setTimeout(tick, 1000);

