js:
var trigger = root.querySelector('.cx5-chain-picker-trigger');
var panel = root.querySelector('.cx5-chain-picker-panel');
var opts = root.querySelectorAll('.cx5-chain-picker-opt');
var nameEl = root.querySelector('.cx5-chain-picker-name');
var idEl = root.querySelector('.cx5-chain-picker-id');
var msEl = root.querySelector('.cx5-chain-picker-ms');
var markEl = root.querySelector('.cx5-chain-picker-mark');
var blockEl = root.querySelector('.cx5-chain-picker-block');
var ageEl = root.querySelector('.cx5-chain-picker-age');
var tones = ['eth', 'base', 'arb', 'poly'];
var open = false, block = 21483902, age = 4;

function setOpen(next){
  open = next;
  panel.hidden = !open;
  trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
  root.classList.toggle('cx5-chain-picker-open', open);
  if (open) {
    var sel = root.querySelector('.cx5-chain-picker-opt-on') || opts[0];
    sel.focus();
  } else {
    trigger.focus();
  }
}
trigger.addEventListener('click', function(){ setOpen(!open); });
panel.addEventListener('keydown', function(e){
  var list = Array.prototype.slice.call(opts);
  var at = list.indexOf(document.activeElement);
  if (e.key === 'Escape') { e.preventDefault(); setOpen(false); }
  else if (e.key === 'ArrowDown') { e.preventDefault(); list[(at + 1 + list.length) % list.length].focus(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); list[(at - 1 + list.length) % list.length].focus(); }
});
for (var i = 0; i < opts.length; i++) {
  opts[i].addEventListener('click', function(e){
    var o = e.currentTarget;
    for (var j = 0; j < opts.length; j++) {
      opts[j].classList.remove('cx5-chain-picker-opt-on');
      opts[j].setAttribute('aria-selected', 'false');
    }
    o.classList.add('cx5-chain-picker-opt-on');
    o.setAttribute('aria-selected', 'true');
    nameEl.textContent = o.getAttribute('data-name');
    idEl.textContent = 'Chain ID ' + o.getAttribute('data-cid');
    msEl.textContent = o.getAttribute('data-ms');
    markEl.textContent = o.getAttribute('data-mark');
    for (var k = 0; k < tones.length; k++) markEl.classList.remove('cx5-chain-picker-mark-' + tones[k]);
    markEl.classList.add('cx5-chain-picker-mark-' + o.getAttribute('data-tone'));
    setOpen(false);
  });
}
document.addEventListener('click', function(e){
  if (!root.isConnected) return;
  if (open && !root.contains(e.target)) setOpen(false);
});
var t = setInterval(function(){
  if (!root.isConnected) { clearInterval(t); return; }
  age += 1;
  if (age > 12) { age = 0; block += 1; blockEl.textContent = block.toLocaleString('en-US'); }
  ageEl.textContent = String(age);
}, 1000);

css:
.cx5-price-alert{--cx5-price-alert-bg:#0F1320;--cx5-price-alert-line:rgba(255,255,255,.09);--cx5-price-alert-txt:#EAF0FA;--cx5-price-alert-dim:#8B95AD;--cx5-price-alert-up:#3DDC97;--cx5-price-alert-down:#FF7B7B;--cx5-price-alert-acc:#F7931A;--cx5-price-alert-p:67.5%;box-sizing:border-box;width:100%;max-width:320px;padding:12px 13px;border:1px solid var(--cx5-price-alert-line);border-radius:14px;background:var(--cx5-price-alert-bg);color:var(--cx5-price-alert-txt);font-family:ui-sans-serif,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-variant-numeric:tabular-nums}
.cx5-price-alert-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.cx5-price-alert-pair{font-size:11px;color:var(--cx5-price-alert-dim);letter-spacing:.03em}
.cx5-price-alert-sym{color:var(--cx5-price-alert-acc);font-weight:800;font-size:12px}
.cx5-price-alert-spot{font-size:12px;color:var(--cx5-price-alert-dim)}
.cx5-price-alert-px{color:var(--cx5-price-alert-txt);font-size:14px;font-weight:700;transition:color .3s ease}
.cx5-price-alert-tickup{color:var(--cx5-price-alert-up)}
.cx5-price-alert-tickdown{color:var(--cx5-price-alert-down)}
.cx5-price-alert-row{display:grid;grid-template-columns:1fr auto;align-items:baseline;gap:2px 8px;margin-top:9px}
.cx5-price-alert-lab{font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--cx5-price-alert-dim)}
.cx5-price-alert-target{justify-self:end;font-size:19px;font-weight:700;letter-spacing:-.02em;color:var(--cx5-price-alert-acc)}
.cx5-price-alert-range{grid-column:1 / -1;-webkit-appearance:none;appearance:none;width:100%;height:5px;margin:7px 0 0;border-radius:999px;background:linear-gradient(90deg,var(--cx5-price-alert-acc) 0,var(--cx5-price-alert-acc) var(--cx5-price-alert-p),rgba(255,255,255,.12) var(--cx5-price-alert-p),rgba(255,255,255,.12) 100%);cursor:pointer}
.cx5-price-alert-range:focus-visible{outline:2px solid var(--cx5-price-alert-acc);outline-offset:5px}
.cx5-price-alert-range::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:15px;height:15px;border-radius:50%;background:#fff;border:3px solid var(--cx5-price-alert-acc);box-shadow:0 2px 7px rgba(0,0,0,.5);cursor:grab;transition:transform .14s ease}
.cx5-price-alert-range::-webkit-slider-thumb:hover{transform:scale(1.14)}
