.cx5-price-alert-below{color:var(--cx5-price-alert-down)}
.cx5-price-alert-arm{display:inline-flex;align-items:center;gap:5px;padding:5px 11px;border-radius:8px;border:1px solid rgba(247,147,26,.4);background:rgba(247,147,26,.13);color:var(--cx5-price-alert-acc);font:inherit;font-size:11.5px;font-weight:700;cursor:pointer;transition:background .18s ease,transform .12s ease}
.cx5-price-alert-arm:hover{background:rgba(247,147,26,.24)}
.cx5-price-alert-arm:active{transform:translateY(1px)}
.cx5-price-alert-arm:focus-visible{outline:2px solid var(--cx5-price-alert-acc);outline-offset:2px}
.cx5-price-alert-bell{width:13px;height:13px}
.cx5-price-alert-armed{border-color:rgba(61,220,151,.45);background:rgba(61,220,151,.14);color:var(--cx5-price-alert-up)}
.cx5-price-alert-armed .cx5-price-alert-bell{animation:cx5-price-alert-swing 2.6s ease-in-out infinite}
@keyframes cx5-price-alert-swing{0%,88%,100%{transform:rotate(0)}91%{transform:rotate(13deg)}95%{transform:rotate(-11deg)}}
@media (prefers-reduced-motion:reduce){.cx5-price-alert-armed .cx5-price-alert-bell{animation:none}.cx5-price-alert-px,.cx5-price-alert-arm{transition:none}}

js:
var range = root.querySelector('.cx5-price-alert-range');
var tv = root.querySelector('.cx5-price-alert-tv');
var pxEl = root.querySelector('.cx5-price-alert-px');
var away = root.querySelector('.cx5-price-alert-away');
var pct = root.querySelector('.cx5-price-alert-pct');
var arm = root.querySelector('.cx5-price-alert-arm');
var spot = 64180.25, armed = false;

function money(n, d){
  return n.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
}
function render(){
  var target = parseFloat(range.value);
  var span = (target - range.min) / (range.max - range.min) * 100;
  root.style.setProperty('--cx5-price-alert-p', span.toFixed(2) + '%');
  tv.textContent = money(target, 0);
  var diff = (target - spot) / spot * 100;
  var up = diff >= 0;
  pct.textContent = Math.abs(diff).toFixed(2) + '%';
  away.firstChild.nodeValue = up ? '▲ ' : '▼ ';
  away.lastChild.nodeValue = up ? ' above spot' : ' below spot';
  away.classList.toggle('cx5-price-alert-below', !up);
}
range.addEventListener('input', render);
arm.addEventListener('click', function(){
  armed = !armed;
  arm.classList.toggle('cx5-price-alert-armed', armed);
  arm.setAttribute('aria-pressed', armed ? 'true' : 'false');
  arm.lastChild.nodeValue = armed ? ' Watching' : ' Arm alert';
});
var t = setInterval(function(){
  if (!root.isConnected) { clearInterval(t); return; }
  var move = (Math.random() - 0.5) * 190;
  var next = Math.min(74800, Math.max(55200, spot + move));
  var up = next >= spot;
  spot = next;
  pxEl.textContent = money(spot, 2);
  pxEl.classList.toggle('cx5-price-alert-tickup', up);
  pxEl.classList.toggle('cx5-price-alert-tickdown', !up);
  render();
}, 1800);
render();
